codeWrong:
/* CSS que remove o foco */
* {
  outline: none;
}

button:focus {
  outline: 0;
}

codeRight:
/* CSS que garante foco visível */
:focus-visible {
  outline: 2px solid #facc15;
  outline-offset: 3px;
  border-radius: 4px;
}

/* Remova apenas quando fornecer
   um estilo alternativo legível */
.custom-focus:focus-visible {
  box-shadow: 0 0 0 3px #facc15;
}

